verification_steps.command:
cd <run>/work/repo && node --version && node --input-type=module -e '
import { landingPath } from "./src/session.js";
const now = Date.now();
console.log("expired:", landingPath({ token: "t", expiresAt: now - 1000 }));
console.log("valid:  ", landingPath({ token: "t", expiresAt: now + 60000 }));
console.log("none:   ", landingPath(null));'

node --test test/session.test.js 2>&1 | grep -E "^(ℹ (pass|fail))|^✔|^✖"; node --input-type=module -e '
import { landingPath } from "./src/session.js";
const now = Date.now();
console.log("expired:", landingPath({ token: "t", expiresAt: now - 1000 }));
console.log("valid:  ", landingPath({ token: "t", expiresAt: now + 60000 }));
console.log("ISO valid:", landingPath({ token: "t", expiresAt: new Date(now + 60000).toISOString() }));
console.log("none:   ", landingPath(null));'
